import { useState } from 'react';
import Button from '../../components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../components/ui/dialog';
import FormField from '../../components/ui/form-field';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select } from '@/components/ui/native-select';
import { toast } from 'sonner';
import type { BudgetItem } from './types';
import { useCreateBudgetItem, useUpdateBudgetItem } from './queries';

const TIPOS = [
  { value: 'mao_de_obra', label: 'Mão de Obra' },
  { value: 'material', label: 'Material' },
  { value: 'hospedagem', label: 'Hospedagem' },
  { value: 'transporte', label: 'Transporte' },
  { value: 'base', label: 'Custo BASE' },
  { value: 'outros', label: 'Outros' },
];

interface OrcamentoModalProps {
  contractId: string;
  item: BudgetItem | null;
  onClose: () => void;
}

/** Modal de criação/edição de item de orçamento. */
export default function OrcamentoModal({
  contractId,
  item,
  onClose,
}: OrcamentoModalProps) {
  const criar = useCreateBudgetItem();
  const editar = useUpdateBudgetItem();
  const isEdit = Boolean(item);

  const [description, setDescription] = useState(item?.description ?? '');
  const [type, setType] = useState(item?.type ?? 'mao_de_obra');
  const [value, setValue] = useState(String(item?.value ?? ''));
  const [notes, setNotes] = useState(item?.notes ?? '');

  const pending = criar.isPending || editar.isPending;

  function submit() {
    if (!description.trim()) {
      toast.error('Descrição obrigatória');
      return;
    }
    const valorNum = Number(value) || 0;
    if (valorNum <= 0) {
      toast.error('Informe um valor válido');
      return;
    }
    const input = {
      description: description.trim(),
      type,
      value: valorNum,
      notes: notes.trim(),
    };
    const handlers = {
      onSuccess: () => {
        toast.success(isEdit ? 'Item atualizado' : 'Item adicionado');
        onClose();
      },
      onError: (e: Error) => toast.error(e.message),
    };
    if (item?.id) {
      editar.mutate({ contractId, budgetId: item.id, input }, handlers);
    } else {
      criar.mutate({ contractId, input }, handlers);
    }
  }

  return (
    <Dialog open onOpenChange={(next) => !next && onClose()}>
      <DialogContent className="p-0 gap-0 w-[92vw] sm:max-w-[680px]">
        <DialogHeader>
          <DialogTitle>
            {isEdit ? 'Editar Item do Orçamento' : 'Novo Item do Orçamento'}
          </DialogTitle>
        </DialogHeader>
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          <FormField label="Descrição *" htmlFor="orc-desc">
            <Input
              id="orc-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Ex: Equipe de campo, aço, diárias..."
            />
          </FormField>
          <div style={{ display: 'flex', gap: 'var(--sp-md)', flexWrap: 'wrap' }}>
            <div style={{ flex: 1, minWidth: 160 }}>
              <FormField label="Categoria *" htmlFor="orc-tipo">
                <Select
                  id="orc-tipo"
                  value={type}
                  onChange={(e) => setType(e.target.value)}
                >
                  {TIPOS.map((t) => (
                    <option key={t.value} value={t.value}>
                      {t.label}
                    </option>
                  ))}
                </Select>
              </FormField>
            </div>
            <div style={{ flex: 1, minWidth: 140 }}>
              <FormField label="Valor Orçado (BRL) *" htmlFor="orc-valor">
                <Input
                  id="orc-valor"
                  type="number"
                  step="0.01"
                  value={value}
                  onChange={(e) => setValue(e.target.value)}
                  placeholder="0,00"
                />
              </FormField>
            </div>
          </div>
          <FormField label="Observações" htmlFor="orc-notes">
            <Textarea
              id="orc-notes"
              rows={2}
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Detalhes adicionais..."
            />
          </FormField>
        </div>
        <DialogFooter>
          <Button variant="secondary" onClick={onClose} disabled={pending}>
            Cancelar
          </Button>
          <Button onClick={submit} disabled={pending}>
            {pending ? 'Salvando…' : isEdit ? 'Atualizar' : 'Adicionar'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
